/**
 * Radio: the list of stations, the selected station (saved), and a tiny cross-fade state machine.
 * Pure (no WebAudio, no DOM): the audio engine reads it, `src/ui/radio.ts` drives it.
 * "auto" keeps the adaptive music (area / activity); any other station overrides it until changed.
 */
import type { TrackId } from './tracks';

export type StationId =
  | 'auto' | 'trail' | 'zoom' | 'sky' | 'rush'
  | 'carnival' | 'beach' | 'disco' | 'spooky' | 'arcade'
  | 'off';

/** Procedural stations (generated by `stations.ts`). */
export type GenStationId = 'carnival' | 'beach' | 'disco' | 'spooky' | 'arcade';

export type StationKind = 'auto' | 'track' | 'gen' | 'off';

export interface Station {
  id: StationId;
  kind: StationKind;
  /** Streamed CC0 loop (kind 'track'). */
  track?: TrackId;
  /** Short name for the "now playing" chip. */
  name: string;
}

/** Cycling order. */
export const STATIONS: readonly Station[] = [
  { id: 'auto', kind: 'auto', name: 'Auto' },
  { id: 'trail', kind: 'track', track: 'explore', name: 'Trail' },
  { id: 'zoom', kind: 'track', track: 'action', name: 'Zoom' },
  { id: 'sky', kind: 'track', track: 'air', name: 'Sky' },
  { id: 'rush', kind: 'track', track: 'urgent', name: 'Rush' },
  { id: 'carnival', kind: 'gen', name: 'Carnival' },
  { id: 'beach', kind: 'gen', name: 'Beach' },
  { id: 'disco', kind: 'gen', name: 'Disco' },
  { id: 'spooky', kind: 'gen', name: 'Boo!' },
  { id: 'arcade', kind: 'gen', name: 'Arcade' },
  { id: 'off', kind: 'off', name: 'Off' },
];

export const DEFAULT_STATION: StationId = 'auto';
export const RADIO_STORAGE_KEY = 'rg.radio.v1';
/** Cross-fade between stations (s). */
export const RADIO_FADE = 0.6;

export function stationById(id: string): Station | undefined {
  return STATIONS.find((s) => s.id === id);
}

/** Cycle helper: wraps around, `dir` is +1 or -1. */
export function stepStation(id: StationId, dir: 1 | -1 = 1): StationId {
  const i = Math.max(0, STATIONS.findIndex((s) => s.id === id));
  return (STATIONS[(i + dir + STATIONS.length) % STATIONS.length] as Station).id;
}

/** Equal-power gains for a cross-fade at progress t (0..1). */
export function crossfadeGains(t: number): { out: number; in: number } {
  const x = Math.min(1, Math.max(0, t));
  return { out: Math.cos((x * Math.PI) / 2), in: Math.sin((x * Math.PI) / 2) };
}

/** Where a station change is: idle, or fading `from` -> `to`. Time is injected (seconds). */
export class Crossfade {
  from: StationId | null = null;
  to: StationId = DEFAULT_STATION;
  private startedAt = 0;
  constructor(private readonly duration = RADIO_FADE) {}

  start(from: StationId, to: StationId, now: number): void {
    this.from = from;
    this.to = to;
    this.startedAt = now;
  }

  /** 0..1 progress (1 when idle). */
  progress(now: number): number {
    if (this.from === null) return 1;
    return Math.min(1, Math.max(0, (now - this.startedAt) / this.duration));
  }

  /** 'idle' or 'fading'; becomes idle once the fade has finished. */
  phase(now: number): 'idle' | 'fading' {
    if (this.from !== null && this.progress(now) >= 1) this.from = null;
    return this.from === null ? 'idle' : 'fading';
  }
}

export interface KeyValueStore {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

export type RadioListener = (id: StationId, previous: StationId) => void;

export class RadioState {
  private id: StationId = DEFAULT_STATION;
  private readonly listeners = new Set<RadioListener>();
  readonly fade = new Crossfade();

  constructor(private readonly store: KeyValueStore | null = null) {
    try {
      const saved = store?.getItem(RADIO_STORAGE_KEY);
      if (saved && stationById(saved)) this.id = saved as StationId;
    } catch {
      /* storage blocked: start on Auto */
    }
  }

  get current(): StationId {
    return this.id;
  }

  get station(): Station {
    return stationById(this.id) ?? (STATIONS[0] as Station);
  }

  /** Select a station; returns false when unknown or unchanged. */
  set(id: StationId, now = 0): boolean {
    if (!stationById(id) || id === this.id) return false;
    const previous = this.id;
    this.id = id;
    this.fade.start(previous, id, now);
    try {
      this.store?.setItem(RADIO_STORAGE_KEY, id);
    } catch {
      /* ignore */
    }
    for (const l of [...this.listeners]) l(id, previous);
    return true;
  }

  next(now = 0): StationId {
    this.set(stepStation(this.id, 1), now);
    return this.id;
  }

  prev(now = 0): StationId {
    this.set(stepStation(this.id, -1), now);
    return this.id;
  }

  subscribe(fn: RadioListener): () => void {
    this.listeners.add(fn);
    return () => this.listeners.delete(fn);
  }
}

let shared: RadioState | null = null;

/** The one radio of the page (saved in localStorage under `rg.radio.v1`). */
export function getRadio(): RadioState {
  if (!shared) {
    const pick = (): KeyValueStore | null => {
      try {
        return typeof localStorage !== 'undefined' ? localStorage : null;
      } catch {
        return null;
      }
    };
    shared = new RadioState(pick());
  }
  return shared;
}

/** Tests only: drop the shared instance. */
export function resetRadioForTests(): void {
  shared = null;
}
